import numpy as np
import pandas as pd
import tensorflow as tf
import joblib
import argparse
import os
import sys

# --- Configuration ---
MODEL_PATH = 'btcusdt_win_loss_model.keras'
SCALER_PATH = 'scaler.joblib'
EXPECTED_ROWS = 480
# --- ALIGNMENT: The exact feature set the model was trained on ---
EXPECTED_COLS = ['open', 'high', 'low', 'close', 'volume', 'histogram', 'signal', 'macd']

def process_and_predict(file_path, model, scaler):
    """
    Processes a single raw CSV file from your backtester and returns a prediction.
    """
    try:
        # Load the raw data file generated by your backtesting script
        df = pd.read_csv(file_path, index_col=0)

        if len(df) != EXPECTED_ROWS:
            print(f"Error: File must contain {EXPECTED_ROWS} rows, but found {len(df)}.")
            return None

        # --- CRITICAL ALIGNMENT STEP 1: Reverse data to chronological order ---
        # Your backtester saves newest-to-oldest, so we flip it for the time-series model.
        df = df.iloc[::-1]
        
        # --- CRITICAL ALIGNMENT STEP 2: Select the exact feature columns ---
        # This ensures the column order and selection match the training data.
        features = df[EXPECTED_COLS]

        # --- CRITICAL ALIGNMENT STEP 3: Scale data using the saved scaler ---
        scaled_features = scaler.transform(features.values)
        
        # --- Reshape for a single prediction: (1, timesteps, features) ---
        reshaped_data = np.expand_dims(scaled_features, axis=0)
        
        # --- Make the prediction ---
        prediction = model.predict(reshaped_data, verbose=0)[0][0]
        return prediction

    except FileNotFoundError:
        print(f"Error: The file could not be found at the specified path: {file_path}")
        return None
    except Exception as e:
        print(f"An error occurred while processing the file: {e}")
        return None

def main():
    """
    Main function to handle user input, load models, and display predictions.
    """
    # --- Step 1: Set up command-line argument parsing ---
    parser = argparse.ArgumentParser(
        description="Predict trade outcome (Win/Loss) from a 480-candle CSV file.",
        formatter_class=argparse.RawTextHelpFormatter
    )
    parser.add_argument(
        '-f', '--file',
        help="Path to the input CSV file to run the prediction against."
    )
    args = parser.parse_args()

    # --- Step 2: Determine the input file path ---
    input_file_path = ""
    if args.file:
        # Method 1: File path is provided via command-line flag
        input_file_path = args.file
        print(f"File provided via command-line flag: {input_file_path}")
    else:
        # Method 2: No flag provided, prompt the user interactively
        try:
            input_file_path = input("\n>>> Please enter the path to the CSV file and press Enter: ")
        except KeyboardInterrupt:
            print("\nOperation cancelled by user. Exiting.")
            sys.exit(0)

    # --- Step 3: Validate file existence ---
    if not os.path.exists(input_file_path):
        print(f"\nError: Input file not found at '{input_file_path}'")
        sys.exit(1)

    # --- Step 4: Load the trained model and scaler ---
    try:
        print("\nLoading the trained model and scaler...")
        model = tf.keras.models.load_model(MODEL_PATH)
        scaler = joblib.load(SCALER_PATH)
        print("Model and scaler loaded successfully.")
    except Exception as e:
        print(f"\nError: Could not load model or scaler. Make sure '{MODEL_PATH}' and '{SCALER_PATH}' are in the same directory.")
        print(f"Details: {e}")
        sys.exit(1)
        
    # --- Step 5: Process the file and make a prediction ---
    print(f"\nProcessing file and making a prediction...")
    prediction_score = process_and_predict(input_file_path, model, scaler)

    # --- Step 6: Display the final result ---
    if prediction_score is not None:
        threshold = 0.5  # Standard threshold for binary classification
        
        print("\n" + "="*30)
        print("       PREDICTION RESULT")
        print("="*30)
        
        if prediction_score > threshold:
            print(f"  Outcome:      WIN")
            print(f"  Confidence:   {prediction_score:.2%}")
        else:
            print(f"  Outcome:      LOSS")
            # For a loss, confidence is how far the score is from 1.0
            print(f"  Confidence:   {1 - prediction_score:.2%}")
        
        print(f"  Raw Score:    {prediction_score:.6f}")
        print("="*30)

if __name__ == '__main__':
    main()
